namespace {
unsigned checks=0,failures=0;
void Check(bool ok,const char* text){++checks;failures+=!ok;std::printf("%s %s\n",ok?"PASS":"FAIL",text);}
void Require(bool ok,const std::string& error){if(!ok)throw std::runtime_error(error);}
PowertrainSettings Graph(){PowertrainSettings s;PowertrainShaft input;input.name="source";input.bearing=2;input.axis={-1,0,0};s.shafts.push_back(input);PowertrainShaft output;output.name="wheel";output.kind=PowertrainShaftKind::Wheel;output.target=4;s.shafts.push_back(output);PowertrainSource source;source.name="drive";source.maxTorque=50;s.sources.push_back(source);PowertrainLink link;link.name="gear:rear";link.connection={3,"right","left"};s.links.push_back(link);return s;}
Scene Fixture(const std::string& asset){Scene scene;auto& root=scene.CreateObject("mechanical assembly");root.powertrain=Graph();auto& carrier=scene.CreateObject("ordinary physical carrier");carrier.parent=1;carrier.body=SceneBodyComponent{};carrier.body->motion=SceneBodyMotion::Dynamic;carrier.body->mass=10;carrier.body->halfExtents={.1f,.1f,.1f};carrier.transform.position={1.5f,0,0};auto& material=scene.CreateObject("load-bearing material");material.parent=1;material.deformable=DeformableSettings{};material.deformable->asset=asset;material.deformable->selfContact=false;material.deformable->material.density=20;DeformableAttachment left;left.group="left";DeformableAttachment right;right.group="right";right.kind=DeformableAttachment::Kind::Body;right.target=2;right.offset={-1.5,0,0};material.deformable->attachments={left,right};auto& wheel=scene.CreateObject("ordinary wheel");wheel.parent=1;wheel.wheel=WheelSettings{};wheel.wheel->chassis=2;wheel.wheel->mount={0,-.2f,0};return scene;}
void Tick(RuntimeWorld& world){world.UpdatePowertrains(1.f/60);world.UpdateWheels(1.f/60);world.ResolvePowertrainLoads(1.f/60);world.Physics().Step(1.f/60);world.PublishWheels();world.PublishPowertrains(1.f/60);}
std::string MechanicalBytes(PowertrainInstance& train){SaveArchive a;train.Persist(a);return a.bytes;}
void SolverControl(){PowertrainSettings s;PowertrainShaft a;a.name="a";a.inertia=1;PowertrainShaft b=a;b.name="b";s.shafts={a,b};PowertrainSource source;source.name="custom";source.maxTorque=40;s.sources={source};PowertrainLink link;link.name="physical link";s.links={link};PowertrainInstance intact,open,legacy;intact.Reset(s);open.Reset(s);legacy.Reset(s);for(auto* t:{&intact,&open,&legacy})t->command.sources[0].customTorque=20;const std::vector<double> mass={1,0,0,1};const auto i=intact.Step(.1,{0,0},mass,{true,true},true,{true});const auto o=open.Step(.1,{0,0},mass,{true,true},true,{false});const auto l=legacy.Step(.1,{0,0},mass,{true,true});Check(i==l&&intact.state.shafts[0].angularVelocity==legacy.state.shafts[0].angularVelocity,"absent prerequisite preserves exact legacy mechanical impulses");Check(intact.state.links[0].active&&intact.state.links[0].connected&&i[1]>0,"intact material prerequisite transmits physical torque");Check(open.state.converged&&!open.state.links[0].active&&!open.state.links[0].connected&&o[0]>0&&o[1]==0,"severed prerequisite removes only transmission, not source operation");Check(open.command.links[0].enabled&&open.command.sources[0].customTorque==20,"physical failure does not mutate driver commands");PowertrainInstance malformed;malformed.Reset(s);const auto bad=malformed.Step(.1,{0,0},mass,{true,true},true,{true,false});Check(!malformed.state.converged&&bad==std::vector<double>({0,0}),"wrong transient continuity shape fails without a partial impulse");}
void AlternatePath(const std::filesystem::path& root){
 const auto path=root/"Assets/loop.judasdeform";const std::string id="83838383838383838383838300000003";auto asset=MakeFractureBlock({2,2,1},{3,.4,.4},false);std::ofstream(path,std::ios::binary)<<EncodeDeformableAsset(asset);AssetDatabase database;database.Scan(root.string(),(root/"Assets").string());AssetRecord tracked;std::string error;Require(database.Track(path.string(),tracked,error,id),error);ResourceManager resources(nullptr,&database);resources.SetBlockingMode(true);
 auto scene=Fixture(id);RuntimeWorld world;world.legacyGameplay=false;Require(world.Build(scene,&resources,error),error);auto* material=world.RuntimeDeformable(3,error);Require(material!=nullptr,error);const auto connection=scene.Find(1)->powertrain->links[0].connection;
 Require(material->fracture.Request(*material->asset->fracture,0,material->fracture.revision)&&material->fracture.Commit(*material->asset->fracture),"first loop cut failed");Check(world.PowertrainConnectionIntact(connection),"single broken bond retains a genuine alternate material path");
 Require(material->fracture.Request(*material->asset->fracture,3,material->fracture.revision)&&material->fracture.Commit(*material->asset->fracture),"second loop cut failed");Check(!world.PowertrainConnectionIntact(connection),"last connecting path loss disconnects the complete rooted attachment patch");
}
void QualifiedStream(const std::filesystem::path& base){
 const auto root=base/"qualified";Project project;std::string error;Require(Project::CreateNew(root.string(),"physical continuity references",project,error),error);
 const std::string assetId="83838383838383838383838300000004";const auto path=root/"Assets/material.judasdeform";std::ofstream(path,std::ios::binary)<<EncodeDeformableAsset(MakeFractureBlock({3,1,1},{3,.4,.4},false));AssetDatabase database;database.Scan(project.RootDir(),project.AssetsDir());AssetRecord record;Require(database.Track(path.string(),record,error,assetId),error);
 auto assembly=Fixture(assetId);Scene support;auto& external=support.CreateObject("foreign physical material");external.deformable=assembly.Find(3)->deformable;external.deformable->attachments[1].kind=DeformableAttachment::Kind::World;external.deformable->attachments[1].target=0;external.deformable->attachments[1].offset={0,0,0};support.CreateObject("invalid foreign body").body=SceneBodyComponent{};
 Require(SaveSceneToFile(support,(root/"Scenes/support.judas").string(),error)&&SaveSceneToFile(assembly,(root/"Scenes/assembly.judas").string(),error),error);
 WorldManifest manifest;WorldRegion a;a.id="support";a.scene="Scenes/support.judas";WorldRegion b;b.id="assembly";b.scene="Scenes/assembly.judas";b.dependencies={"support"};manifest.regions={{a.id,a},{b.id,b}};manifest.references.push_back({"assembly","powertrain-link:gear:rear:connection","support",1,1,true});JobSystem jobs(2);ResourceManager resources(nullptr,&database,&jobs);
 auto wait=[&resources](WorldStreaming& stream,uint64_t token){for(unsigned i=0;i<4000;++i){resources.Pump();stream.Advance(false);auto status=stream.Status(token);if(status&&(status->state=="active"||status->state=="failed"))return status->state;std::this_thread::sleep_for(std::chrono::milliseconds(1));}return std::string("timeout");};Scene bootstrap;auto& body=bootstrap.CreateObject("unrelated root body");body.body=SceneBodyComponent{};body.transform.position={100,0,0};
 {
  RuntimeWorld world;world.legacyGameplay=false;Require(world.Build(bootstrap,&resources,error),error);WorldStreaming stream(world,resources,project,manifest);const auto token=stream.Request("assembly",false,error);const auto state=wait(stream,token);Check(state=="active","actual asynchronous loader installs colon-named physical connection");if(state!="active"){auto status=stream.Status(token);throw std::runtime_error(status?status->error:"stream timeout");}
  const auto owner=stream.Resolve("assembly",1),foreign=stream.Resolve("support",1),placeholder=stream.Resolve("assembly",3);auto* train=world.RuntimePowertrain(owner);Check(train&&foreign&&placeholder&&foreign!=placeholder&&train->settings.links[0].connection.owner==foreign&&world.PowertrainConnectionIntact(train->settings.links[0].connection),"qualified link references real foreign material, not its valid local placeholder");
 }
 {
  RuntimeWorld world;world.legacyGameplay=false;Require(world.Build(bootstrap,&resources,error),error);const auto original=world.Physics().GetTransform(world.RuntimeBody(1));auto invalid=manifest;invalid.references[0].targetLocal=2;WorldStreaming stream(world,resources,project,invalid);auto token=stream.Request("assembly",false,error);Check(wait(stream,token)=="failed","actual loader rejects foreign ordinary body as material continuity");Check(!stream.Resolve("assembly",1)&&world.Physics().IsBodyEnabled(world.RuntimeBody(1))&&world.Physics().GetTransform(world.RuntimeBody(1)).position==original.position,"invalid qualified material publishes no graph and preserves unrelated world physics");
 }
 {
  RuntimeWorld world;world.legacyGameplay=false;Require(world.Build(bootstrap,&resources,error),error);auto invalid=manifest;invalid.references[0].field="powertrain-link:absent:rear:connection";WorldStreaming stream(world,resources,project,invalid);auto token=stream.Request("assembly",false,error);Check(wait(stream,token)=="failed"&&!stream.Resolve("assembly",1),"missing colon-named mechanical link is rejected instead of silently ignored");
 }
}
}

int main(){try{
 SolverControl();std::string error,text,originalFingerprint,changedFingerprint;
 const auto root=std::filesystem::temp_directory_path()/("judas-m83-mechanical-"+std::to_string(std::chrono::steady_clock::now().time_since_epoch().count()));std::filesystem::create_directories(root/"Assets");
 auto asset=MakeFractureBlock({3,1,1},{3,.4,.4},false);const std::string id="83838383838383838383838300000001";const auto assetPath=root/"Assets/material.judasdeform";std::ofstream(assetPath,std::ios::binary)<<EncodeDeformableAsset(asset);AssetDatabase database;database.Scan(root.string(),(root/"Assets").string());AssetRecord tracked;Require(database.Track(assetPath.string(),tracked,error,id),error);ResourceManager resources(nullptr,&database);resources.SetBlockingMode(true);
 auto scene=Fixture(id);Require(ComputeSceneFingerprint(scene,originalFingerprint,error),error);SaveSceneToString(scene,text);Scene round;Check(LoadSceneFromString(text,round,error)&&ScenesEqual(scene,round),"named physical connection round-trips scene serialization");auto plain=scene;plain.Find(1)->powertrain->links[0].connection={};Require(ComputeSceneFingerprint(plain,changedFingerprint,error),error);Check(changedFingerprint!=originalFingerprint,"material connection is fingerprinted authored content");const auto legacy=EncodePowertrainSettings(*plain.Find(1)->powertrain);Check(legacy.find("connection")==std::string::npos,"legacy powertrain codec emits no new default fields");auto encoded=EncodePowertrainSettings(*scene.Find(1)->powertrain);PowertrainSettings decoded;Check(DecodePowertrainSettings(encoded,decoded,error)&&PowertrainSettingsEqual(decoded,*scene.Find(1)->powertrain),"bounded graph codec preserves optional connection identity");auto references=PowertrainReferences(decoded);Check(std::find(references.begin(),references.end(),3)!=references.end(),"material owner participates in ordinary dependency inventory");RemapPowertrainReferences(decoded,[](uint64_t identity){return identity+100;});Check(decoded.links[0].connection.owner==103&&decoded.shafts[1].target==104,"generic prefab/reference remap includes material owner");auto invalid=scene;invalid.Find(1)->powertrain->links[0].connection.attachment="absent";Check(!ComputeSceneFingerprint(invalid,changedFingerprint,error),"absent authored material attachment fails preflight");invalid=scene;invalid.Find(1)->powertrain->links[0].connection.owner=2;Check(!ComputeSceneFingerprint(invalid,changedFingerprint,error),"ordinary body cannot masquerade as material continuity owner");Scene prefab;Check(CreatePrefab(scene,1,prefab,error),"complete material/wheel/transmission family becomes prefab");Scene instances;uint64_t first=0,second=0;SceneTransform placement;Check(InstantiatePrefab(instances,prefab,"83838383838383838383838300000002",placement,first,error),"first independently mapped mechanical prefab instance");placement.position={8,0,0};Check(InstantiatePrefab(instances,prefab,"83838383838383838383838300000002",placement,second,error),"second independently mapped mechanical prefab instance");bool mapped=first&&second&&first!=second;for(const auto& object:instances.Objects())if(object.powertrain){const auto* material=instances.Find(object.powertrain->links[0].connection.owner);mapped&=material&&material->deformable&&material->parent==object.id;}Check(mapped,"independent prefab material references point inside each actual instance");
 RuntimeWorld world;world.legacyGameplay=false;Require(world.Build(scene,&resources,error),error);auto* material=world.RuntimeDeformable(3,error);Require(material!=nullptr,error);auto* train=world.RuntimePowertrain(1);Require(train!=nullptr,"missing mechanical graph");const auto connection=train->settings.links[0].connection;Check(world.PowertrainConnectionIntact(connection),"live endpoint/root patches initially share actual fracture connectivity");train->command.sources[0].customTorque=20;Tick(world);Check(train->state.links[0].connected&&train->state.links[0].active&&world.RuntimeWheel(4)->state.angularVelocity>0,"material-connected graph drives the real wheel angular DOF");const auto before=MechanicalBytes(*train);Require(material->Release("right"),"release failed");world.PublishPowertrainConnections();Check(!train->state.links[0].connected&&!train->state.links[0].active&&MechanicalBytes(*train)==before,"physical attachment loss publishes immediately without corrupting held commands or shaft momentum");const auto spin=world.RuntimeWheel(4)->state.angularVelocity;world.UpdatePowertrains(1.f/60);world.ResolvePowertrainLoads(1.f/60);Check(train->command.links[0].enabled&&!train->state.links[0].active&&world.RuntimeWheel(4)->state.angularVelocity==spin,"lost mount disconnects drive even when JS still requests enabled gear");material->released[1]=0;Check(world.PowertrainConnectionIntact(connection),"explicit material-state restoration reconstructs connection rather than caching failure");world.SetDeformableEnabled(3,false);Check(!world.PowertrainConnectionIntact(connection),"disabled material cannot retain hidden mechanical continuity");world.SetDeformableEnabled(3,true);Check(world.PowertrainConnectionIntact(connection),"reenabling intact material preserves normal dependency availability");Require(material->fracture.Request(*material->asset->fracture,0,material->fracture.revision)&&material->fracture.Commit(*material->asset->fracture),"fracture topology cut failed");Check(!world.PowertrainConnectionIntact(connection)&&!material->released[0]&&!material->released[1],"actual fracture path loss disconnects transmission with both endpoint patches still mounted");auto unrooted=connection;unrooted.rootAttachment.clear();Check(world.PowertrainConnectionIntact(unrooted),"unrooted local connection survives an unrelated remote material cut");auto missing=connection;missing.attachment="absent";Check(!world.PowertrainConnectionIntact(missing),"forged runtime attachment name fails closed");missing=connection;missing.owner=999999;Check(!world.PowertrainConnectionIntact(missing),"missing material entity cannot transmit torque");world.PublishPowertrains(0);std::map<std::string,SaveChunk> chunks;Require(WorldPersistence::Capture(world,chunks,error),error);Scene saved;RuntimeWorld restored;restored.legacyGameplay=false;Require(WorldPersistence::SceneFrom(chunks,saved,error)&&restored.Build(saved,&resources,error,nullptr,nullptr,true)&&WorldPersistence::Prepare(restored,error)&&WorldPersistence::Restore(restored,chunks,error),error);Check(!restored.PowertrainConnectionIntact(connection)&&!restored.RuntimePowertrain(1)->state.links[0].connected,"cold save restores physical cut and derives disconnected transmission before stepping");world.DestroyEntity(3);SceneObject replacement;replacement.body=SceneBodyComponent{};replacement.body->motion=SceneBodyMotion::Dynamic;const auto newer=world.CreateEntity(replacement,nullptr,&error);Check(newer&&newer!=3&&!world.PowertrainConnectionIntact(connection),"destroyed material identity cannot alias a reused rigid-body slot");
 AlternatePath(root);QualifiedStream(root);std::filesystem::remove_all(root);std::printf("M83 mechanical connections checks=%u failures=%u\n",checks,failures);return failures?1:0;
 }catch(const std::exception& e){std::fprintf(stderr,"M83 mechanical connection failure: %s\n",e.what());return 1;}}
